<?php require_once __DIR__.'/lib/auth.php';startAppSession();$count=(int)db()->query('SELECT COUNT(*) FROM users')->fetchColumn();if($count>0){header('Location: login.php');exit;}$error='';$notice='';if($_SERVER['REQUEST_METHOD']==='POST'&&verifyCsrf($_POST['csrf']??'')){try{$name=trim($_POST['name']??'');$email=filter_var(strtolower(trim($_POST['email']??'')),FILTER_VALIDATE_EMAIL);$password=$_POST['password']??'';if(!$name||!$email||strlen($password)<8)throw new RuntimeException('Valid name, email and minimum 8-character password required.');$s=db()->prepare('INSERT INTO users(name,email,password_hash) VALUES(?,?,?)');$s->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT)]);header('Location: login.php?setup=1');exit;}catch(Throwable $e){$error=$e->getMessage();}}$mode='setup';require __DIR__.'/views/auth.php';
